#!/bin/sh
# Media Source Optimizer core entrypoint (also installed as `mso` for `docker exec <ctr> mso …`).
#
#   api | worker | migrate [args] | backup [args]   → python -m mso <role> …
#   init                                            → one-shot bootstrap (dirs, ownership, DB password)
#   anything else                                   → exec as-is
#
# Database URL: MSO_DATABASE_URL wins when set. Otherwise it is assembled from MSO_DB_HOST/PORT/NAME/USER
# and the password in MSO_DB_PASSWORD_FILE (generated by `init`, never part of the compose file).
set -eu

build_db_url() {
  if [ -n "${MSO_DATABASE_URL:-}" ] || [ -z "${MSO_DB_PASSWORD_FILE:-}" ]; then
    return 0
  fi
  if [ ! -r "$MSO_DB_PASSWORD_FILE" ]; then
    echo "mso: databasewachtwoordbestand $MSO_DB_PASSWORD_FILE ontbreekt of is onleesbaar (draaide 'init'?)" >&2
    exit 78
  fi
  MSO_DATABASE_URL=$(python - <<'PY'
import os
from urllib.parse import quote
with open(os.environ["MSO_DB_PASSWORD_FILE"], encoding="utf-8") as fh:
    pw = fh.read().strip()
e = os.environ
print(f"postgresql://{quote(e.get('MSO_DB_USER', 'mso'), safe='')}:{quote(pw, safe='')}@"
      f"{e.get('MSO_DB_HOST', 'postgres')}:{e.get('MSO_DB_PORT', '5432')}/{quote(e.get('MSO_DB_NAME', 'mso'), safe='')}")
PY
)
  export MSO_DATABASE_URL
}

wait_for_db() {
  # postgres is already healthy when compose starts us (depends_on), but a manual `docker run` or a
  # database restart may race; retry briefly instead of crash-looping.
  python - <<'PY'
import os, sys, time
import psycopg
deadline = time.monotonic() + float(os.environ.get("MSO_DB_WAIT_S", "60"))
while True:
    try:
        psycopg.connect(os.environ["MSO_DATABASE_URL"], connect_timeout=3).close()
        sys.exit(0)
    except Exception as exc:  # noqa: BLE001
        if time.monotonic() > deadline:
            print(f"mso: database niet bereikbaar: {type(exc).__name__}", file=sys.stderr)
            sys.exit(75)
        time.sleep(2)
PY
}

# invoked as `mso …` (symlink): always the Python CLI
if [ "$(basename "$0")" = "mso" ]; then
  build_db_url
  exec python -m mso "$@"
fi

role="${1:-api}"
[ $# -gt 0 ] && shift
case "$role" in
  api)
    build_db_url; wait_for_db
    exec python -m mso api --port "${MSO_API_PORT:-8200}" \
      --forwarded-allow-ips "${MSO_FORWARDED_ALLOW_IPS:-127.0.0.1}" "$@" ;;
  worker|migrate|backup)
    build_db_url; wait_for_db
    exec python -m mso "$role" "$@" ;;
  init)
    exec python /usr/local/lib/mso-docker/init.py "$@" ;;
  *)
    build_db_url
    exec "$role" "$@" ;;
esac
